1	/**
2	 * Claude Code in-sandbox runner.
3	 *
4	 * This file is shipped INTO the sandbox by the orchestrator and executed there as
5	 * `node __agent_eval__/run.mjs '<AgentRunInput JSON>'`. It is intentionally
6	 * ZERO-DEPENDENCY (only `node:*` builtins) because the sandbox only has the
7	 * fixture's own deps + the installed `claude` CLI — it cannot import anything from
8	 * the @vercel/agent-eval package.
9	 *
10	 * Dual mode:
11	 *   - runnable: invoked directly → reads argv, runs the agent, writes the result
12	 *     file + prints a status line, exits 0.
13	 *   - importable: `import { runAgent } from './run.mjs'` → returns a RunnerResult
14	 *     (no file write, no exit). This is what a future in-sandbox judge reuses.
15	 *
16	 * `buildClaudeCodeCliArgs` and `extractObservedModelFromClaudeTranscript` are
17	 * exported so the host unit tests can verify them directly (the test imports them
18	 * from this very file, so there is no risk of the tested logic drifting from the
19	 * logic the sandbox actually runs).
20	 */
21	
22	import { spawnSync } from 'node:child_process';
23	import { mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
24	import { homedir } from 'node:os';
25	import { dirname, join } from 'node:path';
26	import { fileURLToPath } from 'node:url';
27	
28	/**
29	 * Build the Claude Code CLI argument list.
30	 *
31	 * Order is regression-sensitive (preserved verbatim from the old adapter):
32	 * `--allowedTools` is variadic — it keeps consuming positional tokens until the
33	 * next flag. So (1) the tools must be a single comma-separated value, and (2)
34	 * `--allowedTools` must be followed by another flag, never directly by the prompt.
35	 * `--dangerously-skip-permissions` is always emitted and terminates the variadic
36	 * capture before the trailing positional prompt (the #141 regression).
37	 *
38	 * @param {{prompt:string, model?:string, webResearch?:boolean, agentOptions?:Record<string,unknown>}} input
39	 * @returns {string[]}
40	 */
41	export function buildClaudeCodeCliArgs(input) {
42	  const cliArgs = ['--print'];
43	  if (input.webResearch) {
44	    cliArgs.push('--allowedTools', 'WebSearch,WebFetch');
45	  }
46	  if (input.model) {
47	    cliArgs.push('--model', input.model);
48	  }
49	  cliArgs.push('--dangerously-skip-permissions');
50	  const effort = input.agentOptions?.effort;
51	  if (effort) {
52	    cliArgs.push('--effort', String(effort));
53	  }
54	  cliArgs.push(input.prompt);
55	  return cliArgs;
56	}
57	
58	/**
59	 * Scan a Claude Code transcript (JSONL) for the last `message.model` seen.
60	 * Preserved verbatim from the old adapter. Non-JSON lines are ignored.
61	 *
62	 * @param {string|undefined|null} transcript
63	 * @returns {string|undefined}
64	 */
65	export function extractObservedModelFromClaudeTranscript(transcript) {
66	  if (!transcript) return undefined;
67	
68	  let observedModel;
69	  for (const line of transcript.split('\n')) {
70	    if (!line.trim()) continue;
71	    try {
72	      const event = JSON.parse(line);
73	      if (typeof event.message?.model === 'string') {
74	        observedModel = event.message.model;
75	      }
76	    } catch {
77	      // Ignore non-JSON transcript lines.
78	    }
79	  }
80	  return observedModel;
81	}
82	
83	/**
84	 * Locate + read the Claude Code transcript file.
85	 *
86	 * Claude Code writes JSONL transcripts to
87	 * `~/.claude/projects/{cwd-with-slashes-as-dashes}/{session}.jsonl`. We pick the
88	 * newest `.jsonl` by mtime — the equivalent of the old adapter's
89	 * `ls -t ~/.claude/projects/<path>/*.jsonl | head -1`.
90	 *
91	 * Best-effort: any failure → null (never throws).
92	 *
93	 * @param {string} cwd post-relocation sandbox cwd (e.g. /workspace)
94	 * @returns {string|null}
95	 */
96	function captureClaudeTranscript(cwd) {
97	  try {
98	    const projectPath = cwd.replace(/\//g, '-');
99	    const dir = join(homedir(), '.claude', 'projects', projectPath);
100	    const newest = readdirSync(dir)
101	      .filter((f) => f.endsWith('.jsonl'))
102	      .map((f) => {
103	        const full = join(dir, f);
104	        return { full, mtime: statSync(full).mtimeMs };
105	      })
106	      .sort((a, b) => b.mtime - a.mtime)[0];
107	    if (!newest) return null;
108	    return readFileSync(newest.full, 'utf8') || null;
109	  } catch {
110	    return null;
111	  }
112	}
113	
114	/**
115	 * Run Claude Code over the workspace at `input.cwd` and return a RunnerResult.
116	 *
117	 * Auth (ANTHROPIC_BASE_URL/ANTHROPIC_AUTH_TOKEN/...) arrives via process.env — the
118	 * orchestrator sets it on the `node run.mjs` invocation, and we pass process.env
119	 * straight through to the CLI. The runner never handles secrets itself.
120	 *
121	 * @param {import('../plugin/contract.js').AgentRunInput} input
122	 * @returns {Promise<import('../plugin/contract.js').RunnerResult>}
123	 */
124	export async function runAgent(input) {
125	  const args = buildClaudeCodeCliArgs(input);
126	
127	  // spawnSync (not a shell string): the prompt is a plain argv element, so there is
128	  // no shell quoting/escaping to get wrong. Blocking is fine — the runner has
129	  // nothing else to do while the agent works. The sandbox-level timeout bounds it.
130	  const res = spawnSync('claude', args, {
131	    cwd: input.cwd,
132	    env: process.env,
133	    encoding: 'utf8',
134	    maxBuffer: 64 * 1024 * 1024,
135	  });
136	
137	  const stdout = res.stdout || '';
138	  const stderr = res.stderr || '';
139	  // Preserve the old concatenation order: stdout THEN stderr.
140	  const output = stdout + stderr;
141	  // spawnSync sets status=null + error when the binary can't be spawned at all.
142	  const agentExitCode = res.status == null ? -1 : res.status;
143	
144	  // Capture transcript + observed model regardless of success (the old adapter did
145	  // this even on the non-zero-exit path).
146	  const transcript = captureClaudeTranscript(input.cwd);
147	  const observedModel = extractObservedModelFromClaudeTranscript(transcript) ?? null;
148	
149	  if (res.error || agentExitCode !== 0) {
150	    // Mirror the old error string: last 5 lines of output, else a coded fallback.
151	    const errorLines = output.trim().split('\n').slice(-5).join('\n');
152	    const fallback = res.error
153	      ? `Failed to run claude: ${res.error.message}`
154	      : `Claude Code exited with code ${agentExitCode}`;
155	    return {
156	      ok: false,
157	      output,
158	      transcript,
159	      observedModel,
160	      error: errorLines || fallback,
161	      agentExitCode,
162	    };
163	  }
164	
165	  return { ok: true, output, transcript, observedModel, error: null, agentExitCode };
166	}
167	
168	/* ─────────────────────────── runnable (CLI) entry ─────────────────────────── */
169	
170	// True when this file is executed directly (`node run.mjs ...`), false when imported.
171	const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
172	
173	if (isMain) {
174	  // argv[2] is the AgentRunInput JSON (never contains secrets).
175	  const input = JSON.parse(process.argv[2]);
176	
177	  // Always produce a RunnerResult, even if the runner itself throws, so the host
178	  // always has a result file to read (node exit code stays 0 except on a truly
179	  // unrecoverable crash before we can write).
180	  let result;
181	  try {
182	    result = await runAgent(input);
183	  } catch (e) {
184	    result = {
185	      ok: false,
186	      output: '',
187	      transcript: null,
188	      observedModel: null,
189	      error: e && e.message ? e.message : String(e),
190	      agentExitCode: -1,
191	    };
192	  }
193	
194	  // Source of truth: the result file the host reads back via sandbox.readFile.
195	  try {
196	    mkdirSync(dirname(input.resultPath), { recursive: true });
197	    writeFileSync(input.resultPath, JSON.stringify(result));
198	  } catch {
199	    // If the file can't be written, the host falls back to the marker line below.
200	  }
201	
202	  // Fallback channel: a compact status line (no transcript — it can be huge).
203	  process.stdout.write(
204	    '__AGENT_RESULT__ ' +
205	      JSON.stringify({
206	        ok: result.ok,
207	        observedModel: result.observedModel,
208	        error: result.error,
209	        agentExitCode: result.agentExitCode,
210	      }) +
211	      '\n'
212	  );
213	
214	  // Exit 0: "the runner ran". Agent success/failure is conveyed via result.ok, not
215	  // the node exit code (the host distinguishes the two).
216	  process.exit(0);
217	}
