/* ─── View transitions ─────────────────────────────────────────── */

/* Directional page slides, keyed off the transition types set by
   <Link transitionTypes={...}> and mapped to these classes by the
   <ViewTransition> boundary in the root layout. */
@keyframes vt-slide-out-left {
  to {
    transform: translateX(-25%);
    opacity: 0;
  }
}

@keyframes vt-slide-in-from-right {
  from {
    transform: translateX(25%);
    opacity: 0;
  }
}

@keyframes vt-slide-out-right {
  to {
    transform: translateX(25%);
    opacity: 0;
  }
}

@keyframes vt-slide-in-from-left {
  from {
    transform: translateX(-25%);
    opacity: 0;
  }
}

::view-transition-old(*.page-slide-forward) {
  animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-out-left;
}

::view-transition-new(*.page-slide-forward) {
  animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-in-from-right;
}

::view-transition-old(*.page-slide-back) {
  animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-out-right;
}

::view-transition-new(*.page-slide-back) {
  animation: 300ms cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-in-from-left;
}

/* Suspense skeleton → content */
@keyframes vt-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes vt-fade-in {
  from {
    opacity: 0;
  }
}

::view-transition-old(*.content-fade) {
  animation: 200ms ease both vt-fade-out;
}

::view-transition-new(*.content-fade) {
  animation: 200ms ease both vt-fade-in;
}

@media (prefers-reduced-motion: reduce) {
  /* Finish every view transition instantly: content still swaps, but
     nothing slides, morphs, or fades. */
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

